  4→// Extract text and image content from message content (string or array of blocks)
  5→interface ExtractedContent {
  6→  text: string;
  7→  images: Array<{ mediaType: string; data: string }>;
  8→  hasToolResults: boolean;
  9→}
 10→
 11→// Pattern for image references that Claude Code outputs when it "reads" an image.
 12→// These are text markers like "[Image: source: /path/to/file.png]" - not actual image data.
 13→// We strip these since the actual images are rendered from base64 content blocks.
 14→const IMAGE_REFERENCE_PATTERN = /\[Image: source: [^\]]+\]/g;
 15→
 16→function extractTextContent(content: unknown): ExtractedContent {
 17→  if (typeof content === "string") {
 18→    return {
 19→      text: content.replace(IMAGE_REFERENCE_PATTERN, "").trim(),
 20→      images: [],
 21→      hasToolResults: false,
 22→    };
 23→  }
 24→  if (!Array.isArray(content)) {
 25→    return { text: "", images: [], hasToolResults: false };
 26→  }
 27→
 28→  let text = "";
 29→  const images: Array<{ mediaType: string; data: string }> = [];
 30→  let hasToolResults = false;
 31→
 32→  for (const block of content) {
 33→    if (typeof block === "object" && block !== null) {
 34→      const b = block as Record<string, unknown>;
 35→      if (b.type === "text") {
 36→        text += (b.text as string) || "";
 37→      } else if (b.type === "tool_result") {
 38→        hasToolResults = true;
 39→      } else if (b.type === "image") {
 40→        const source = b.source as Record<string, unknown> | undefined;
 41→        if (source?.type === "base64" && source.data && source.media_type) {
 42→          images.push({
 43→            mediaType: source.media_type as string,
 44→            data: source.data as string,
 45→          });
 46→        }
 47→      }
 48→    }
 49→  }
 50→  // Strip image reference markers from text (see comment above)
 51→  text = text.replace(IMAGE_REFERENCE_PATTERN, "").trim();
 52→
 53→  return { text, images, hasToolResults };
 54→}
