 56→// Extract tool_use blocks from message content
 57→function extractToolUseBlocks(content: unknown): ToolUseBlock[] {
 58→  if (!Array.isArray(content)) return [];
 59→
 60→  const toolUses: ToolUseBlock[] = [];
 61→  for (const block of content) {
 62→    if (typeof block === "object" && block !== null) {
 63→      const b = block as Record<string, unknown>;
 64→      if (b.type === "tool_use" && b.id && b.name) {
 65→        toolUses.push({
 66→          id: b.id as string,
 67→          name: b.name as string,
 68→          input: (b.input as Record<string, unknown>) || {},
 69→        });
 70→      }
 71→    }
 72→  }
 73→  return toolUses;
 74→}
