 76→// Extract tool_result metadata from a tool result record
 77→function extractToolResultMetadata(
 78→  parsed: Record<string, unknown>,
 79→): ToolCallResult | undefined {
 80→  const toolUseResult = parsed.toolUseResult as
 81→    | Record<string, unknown>
 82→    | undefined;
 83→  if (!toolUseResult) return undefined;
 84→
 85→  const result: ToolCallResult = {
 86→    type: (toolUseResult.type as "text" | "error") || "text",
 87→  };
 88→
 89→  // For file reads
 90→  const file = toolUseResult.file as Record<string, unknown> | undefined;
 91→  if (file) {
 92→    result.file = {
 93→      filePath: file.filePath as string,
 94→      numLines: file.numLines as number | undefined,
 95→    };
 96→  }
 97→
 98→  // For errors
 99→  if (toolUseResult.error) {
100→    result.error = toolUseResult.error as string;
101→    result.type = "error";
102→  }
103→
104→  // For AskUserQuestion - extract user's answers
105→  const answers = toolUseResult.answers as Record<string, string> | undefined;
106→  if (answers) {
107→    result.answers = answers;
108→  }
109→
110→  return result;
