113→/**
114→ * Parse Claude Code JSONL transcript into TranscriptMessage[].
115→ * Returns a natural conversation: user prompt -> final assistant reply (before next user prompt).
116→ * Also extracts tool calls made during each assistant turn.
117→ */
118→function parseClaudeCodeTranscript(jsonlContent: string): TranscriptMessage[] {
119→  const lines = jsonlContent.split("\n").filter((line) => line.trim());
120→
121→  // Internal types for collecting data
122→  type InternalMessage = {
123→    role: "user" | "assistant";
124→    content: string;
125→    images: Array<{ mediaType: string; data: string }>;
126→    timestamp: string;
127→    id: string;
128→  };
129→
130→  // Collect all tool_use records: id -> { name, input, timestamp }
131→  type ToolUseData = Omit<ToolCall, "id" | "result">;
132→  const toolUseById = new Map<string, ToolUseData>();
133→
134→  // Collect all tool_result records: tool_use_id -> result metadata
135→  const toolResultById = new Map<string, ToolCallResult>();
136→
137→  // First pass: collect tool_use and tool_result records
138→  for (const line of lines) {
139→    let parsed: Record<string, unknown>;
140→    try {
141→      parsed = JSON.parse(line);
142→    } catch {
143→      continue;
144→    }
145→
146→    const type = parsed.type as string | undefined;
147→    const message = parsed.message as Record<string, unknown> | undefined;
148→    const timestamp = (parsed.timestamp as string) || new Date().toISOString();
149→
150→    if (type === "assistant" && message?.content) {
151→      // Check for tool_use blocks in assistant messages
152→      const toolUses = extractToolUseBlocks(message.content);
153→      for (const tu of toolUses) {
154→        toolUseById.set(tu.id, {
155→          name: tu.name,
156→          input: tu.input,
157→          timestamp,
158→        });
159→      }
160→    } else if (type === "user" && message?.content) {
161→      // Check for tool_result blocks (they come as "user" type messages)
162→      const content = message.content as unknown[];
163→      if (Array.isArray(content)) {
164→        for (const block of content) {
165→          if (typeof block === "object" && block !== null) {
166→            const b = block as Record<string, unknown>;
167→            if (b.type === "tool_result" && b.tool_use_id) {
168→              const resultMeta = extractToolResultMetadata(parsed);
169→              if (resultMeta) {
170→                toolResultById.set(b.tool_use_id as string, resultMeta);
171→              }
172→            }
173→          }
174→        }
175→      }
176→    }
177→  }
178→
179→  // Second pass: collect messages and track tool calls per turn
180→  const messages: InternalMessage[] = [];
181→  const assistantByRequestId = new Map<string, number>();
182→
183→  // Track tool calls in the current turn (between user messages)
184→  // Key is the index in messages array where we'll eventually attach them
185→  const toolCallsPerTurn: ToolCall[] = [];
186→
187→  for (const line of lines) {
188→    let parsed: Record<string, unknown>;
189→    try {
190→      parsed = JSON.parse(line);
191→    } catch {
192→      continue;
193→    }
194→
195→    const type = parsed.type as string | undefined;
196→    if (type !== "user" && type !== "assistant") continue;
197→
198→    const message = parsed.message as Record<string, unknown> | undefined;
199→    if (!message) continue;
200→
201→    const timestamp = (parsed.timestamp as string) || new Date().toISOString();
202→
203→    if (type === "assistant") {
204→      // Check for tool_use blocks first
205→      const toolUses = extractToolUseBlocks(message.content);
206→      for (const tu of toolUses) {
207→        const toolData = toolUseById.get(tu.id);
208→        if (toolData) {
209→          const toolCall: ToolCall = {
210→            id: tu.id,
211→            name: tu.name,
212→            input: tu.input,
213→            timestamp: toolData.timestamp,
214→            result: toolResultById.get(tu.id),
215→          };
216→          toolCallsPerTurn.push(toolCall);
217→        }
218→      }
219→
220→      // Also extract text content for the message
221→      const { text, images } = extractTextContent(message.content);
222→      const content = text.trim();
223→      const requestId = (parsed.requestId as string) || (message.id as string);
224→      if (!requestId) continue;
225→
226→      const existingIdx = assistantByRequestId.get(requestId);
227→      if (existingIdx !== undefined) {
228→        // Streaming update: replace with latest content
229→        if (content) {
230→          messages[existingIdx].content = content;
231→          messages[existingIdx].timestamp = timestamp;
232→        }
233→        if (images.length > 0) {
234→          messages[existingIdx].images = images;
235→        }
236→      } else {
237→        assistantByRequestId.set(requestId, messages.length);
238→        messages.push({
239→          role: "assistant",
240→          content,
241→          images,
242→          timestamp,
243→          id: (message.id as string) || crypto.randomUUID(),
244→        });
245→      }
246→    } else {
247→      // User message
248→      const { text, images, hasToolResults } = extractTextContent(
249→        message.content,
250→      );
251→      const content = text.trim();
252→
253→      // Skip user messages that are only tool results and have no text/images
254→      if ((!content && images.length === 0) || hasToolResults) continue;
255→
256→      messages.push({
257→        role: "user",
258→        content,
259→        images,
260→        timestamp,
261→        id: (parsed.uuid as string) || crypto.randomUUID(),
262→      });
263→    }
264→  }
265→
266→  // Sort by timestamp
267→  messages.sort(
268→    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
269→  );
270→
271→  // Sort tool calls by timestamp for proper ordering
272→  toolCallsPerTurn.sort(
273→    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
274→  );
275→
276→  // Build result: keep only the last assistant before each user (and final assistant)
277→  // Attach tool calls that happened between user messages to the assistant response
278→  const result: TranscriptMessage[] = [];
279→  let lastAssistant: (InternalMessage & { toolCalls?: ToolCall[] }) | null =
280→    null;
281→  let lastUserTimestamp: string | null = null;
282→
283→  const hasContent = (m: InternalMessage) => m.content || m.images.length > 0;
284→
285→  // Helper to get tool calls between two timestamps
286→  const getToolCallsInRange = (
287→    startTs: string | null,
288→    endTs: string,
289→  ): ToolCall[] => {
290→    return toolCallsPerTurn.filter((tc) => {
291→      const tcTime = new Date(tc.timestamp).getTime();
292→      const endTime = new Date(endTs).getTime();
293→      if (startTs === null) {
294→        return tcTime <= endTime;
295→      }
296→      const startTime = new Date(startTs).getTime();
297→      return tcTime > startTime && tcTime <= endTime;
298→    });
299→  };
300→
301→  for (const msg of messages) {
302→    if (msg.role === "user") {
303→      if (lastAssistant && hasContent(lastAssistant)) {
304→        // Get tool calls for this turn (between last user and this assistant)
305→        const turnToolCalls = getToolCallsInRange(
306→          lastUserTimestamp,
307→          lastAssistant.timestamp,
308→        );
309→        result.push({
310→          ...lastAssistant,
311→          images:
312→            lastAssistant.images.length > 0 ? lastAssistant.images : undefined,
313→          toolCalls: turnToolCalls,
314→        });
315→      }
316→      result.push({
317→        ...msg,
318→        images: msg.images.length > 0 ? msg.images : undefined,
319→      });
320→      lastUserTimestamp = msg.timestamp;
321→      lastAssistant = null;
322→    } else if (hasContent(msg)) {
323→      lastAssistant = msg;
324→    }
325→  }
326→
327→  // Handle final assistant message
328→  if (lastAssistant && hasContent(lastAssistant)) {
329→    const turnToolCalls = getToolCallsInRange(
330→      lastUserTimestamp,
331→      lastAssistant.timestamp,
332→    );
333→    result.push({
334→      ...lastAssistant,
335→      images:
336→        lastAssistant.images.length > 0 ? lastAssistant.images : undefined,
337→      toolCalls: turnToolCalls,
338→    });
339→  }
340→
341→  return result;
342→}
