344→/**
345→ * Strip Claude Code internal XML tags from message content.
346→ * These tags are injected by the system and should never be shown to users.
347→ */
348→function stripInternalTags(content: string): string {
349→  return content
350→    .replace(/<command-message>[\s\S]*?<\/command-message>/g, "")
351→    .replace(/<command-name>[\s\S]*?<\/command-name>/g, "")
352→    .replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, "")
353→    .trim();
354→}
