359→export class ClaudeCodeParser implements TranscriptParser {
360→  readonly name = "Claude Code";
361→
362→  parse(jsonlContent: string): TranscriptParseResult {
363→    const messages = parseClaudeCodeTranscript(jsonlContent);
364→
365→    // Strip internal tags from all message content
366→    for (const msg of messages) {
367→      if (msg.content) {
368→        msg.content = stripInternalTags(msg.content);
369→      }
370→    }
371→
372→    return {
373→      messages,
374→      isFallback: false,
375→    };
376→  }
377→}
