216→// SliceFromMessage returns a Gemini transcript scoped to messages starting from
217→// startMessageIndex. This is the Gemini equivalent of transcript.SliceFromLine —
218→// for Gemini's single JSON blob, scoping is done by message index rather than line offset.
219→// Returns the original data if startMessageIndex <= 0.
220→// Returns nil, nil if startMessageIndex exceeds the number of messages.
221→func SliceFromMessage(data []byte, startMessageIndex int) ([]byte, error) {
222→	if len(data) == 0 || startMessageIndex <= 0 {
223→		return data, nil
224→	}
225→
226→	t, err := ParseTranscript(data)
227→	if err != nil {
228→		return nil, fmt.Errorf("failed to parse transcript for slicing: %w", err)
229→	}
230→
231→	if startMessageIndex >= len(t.Messages) {
232→		return nil, nil
233→	}
234→
235→	scoped := &GeminiTranscript{
236→		Messages: t.Messages[startMessageIndex:],
237→	}
238→
239→	out, err := json.Marshal(scoped)
240→	if err != nil {
241→		return nil, fmt.Errorf("failed to marshal scoped transcript: %w", err)
242→	}
243→	return out, nil
244→}
