  1→import type { TranscriptMessage, ToolCall } from "../../types";
  2→import type { TranscriptParser, TranscriptParseResult } from "./types";
  3→
  4→interface GeminiRawMessage {
  5→  id?: string;
  6→  type?: string;
  7→  content?: unknown;
  8→  timestamp?: string;
  9→  toolCalls?: Array<{
 10→    id: string;
 11→    name: string;
 12→    args?: Record<string, unknown>;
 13→  }>;
 14→}
 15→
 16→interface GeminiLog {
 17→  messages?: GeminiRawMessage[];
 18→}
 19→
 20→/**
 21→ * Extract text from Gemini message content.
 22→ * Handles both string content and array-of-parts format:
 23→ *   - string: "response text"
 24→ *   - array:  [{"text": "prompt text"}, ...]
 25→ */
 26→function extractTextContent(content: unknown): string {
 27→  if (typeof content === "string") return content;
 28→  if (!Array.isArray(content)) return "";
 29→
 30→  const texts: string[] = [];
 31→  for (const part of content) {
 32→    if (typeof part === "object" && part !== null) {
 33→      const p = part as Record<string, unknown>;
 34→      if (typeof p.text === "string" && p.text) {
 35→        texts.push(p.text);
 36→      }
 37→    }
 38→  }
 39→  return texts.join("\n");
 40→}
 41→
 42→function extractToolCalls(
 43→  msg: GeminiRawMessage,
 44→  timestamp: string,
 45→): ToolCall[] | undefined {
 46→  if (!msg.toolCalls || msg.toolCalls.length === 0) return undefined;
 47→
 48→  return msg.toolCalls.map((tc) => ({
 49→    id: tc.id,
 50→    name: tc.name,
 51→    input: (tc.args ?? {}) as Record<string, unknown>,
 52→    timestamp,
 53→  }));
 54→}
 55→
 56→/**
 57→ * Parse a Gemini CLI transcript into TranscriptMessage[].
 58→ * Format: single JSON object with a `messages` array.
 59→ * User messages have type "user", assistant messages have type "gemini".
 60→ */
 61→function parseGeminiTranscript(jsonContent: string): TranscriptMessage[] {
 62→  let log: GeminiLog;
 63→  try {
 64→    log = JSON.parse(jsonContent);
 65→  } catch {
 66→    return [];
 67→  }
 68→
 69→  if (!Array.isArray(log.messages)) return [];
 70→
 71→  const messages: TranscriptMessage[] = [];
 72→
 73→  for (const msg of log.messages) {
 74→    if (msg.type !== "user" && msg.type !== "gemini") continue;
 75→
 76→    const role: "user" | "assistant" =
 77→      msg.type === "user" ? "user" : "assistant";
 78→    const timestamp = msg.timestamp || new Date().toISOString();
 79→
 80→    messages.push({
 81→      id: msg.id || crypto.randomUUID(),
 82→      role,
 83→      content: extractTextContent(msg.content),
 84→      timestamp,
 85→      toolCalls:
 86→        role === "assistant" ? extractToolCalls(msg, timestamp) : undefined,
 87→    });
 88→  }
 89→
 90→  return messages;
 91→}
 92→
 93→/**
 94→ * Parser for Gemini CLI transcripts.
 95→ */
 96→export class GeminiParser implements TranscriptParser {
 97→  readonly name = "Gemini CLI";
 98→
 99→  parse(jsonContent: string): TranscriptParseResult {
100→    const messages = parseGeminiTranscript(jsonContent);
101→
102→    return {
103→      messages,
104→      isFallback: false,
105→    };
106→  }
107→}
