305→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
306→// project directories if needed.
307→func resolveAndValidateTranscript(ctx context.Context, sessionID string, agentName types.AgentName, ag agent.Agent) (string, error) {
308→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
309→	if err != nil {
310→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
311→	}
312→	// Agents use cwd-derived project directories, so the transcript may be stored under
313→	// a different project directory if the session was started from a different working directory.
314→	if _, statErr := os.Stat(transcriptPath); statErr != nil {
315→		if found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag); searchErr == nil {
316→			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
317→			transcriptPath = found
318→		} else {
319→			logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
320→		}
321→	}
322→	if _, statErr := os.Stat(transcriptPath); statErr != nil {
323→		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
324→	}
325→	return transcriptPath, nil
326→}
