392→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
393→// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
394→func extractFirstPromptFromTranscript(data []byte) string {
395→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
396→	lines, err := transcript.ParseFromBytes(data)
397→	if err == nil {
398→		for _, line := range lines {
399→			if line.Type == transcript.TypeUser {
400→				prompt := extractTextFromMessage(line.Message)
401→				if prompt != "" {
402→					return prompt
403→				}
404→			}
405→		}
406→	}
407→
408→	// Fallback: try Gemini JSON format {"messages": [...]}
409→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
410→		return prompts[0]
411→	}
412→
413→	return ""
414→}
