460→// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
461→// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
462→func countUserTurns(data []byte) int {
463→	// Try JSONL format first — use extractTextFromMessage to distinguish
464→	// real user prompts from tool_result messages (both have type "user").
465→	lines, err := transcript.ParseFromBytes(data)
466→	if err == nil {
467→		count := 0
468→		for _, line := range lines {
469→			if line.Type == transcript.TypeUser {
470→				if extractTextFromMessage(line.Message) != "" {
471→					count++
472→				}
473→			}
474→		}
475→		if count > 0 {
476→			return count
477→		}
478→	}
479→
480→	// Fallback: Gemini JSON format
481→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
482→		return len(prompts)
483→	}
484→
485→	return 0
486→}
