488→// extractModelFromTranscript extracts the model name from a JSONL transcript.
489→// Best-effort: returns empty string if the transcript format doesn't include model info
490→// (e.g., Gemini stores model info in hook events, not the transcript).
491→func extractModelFromTranscript(data []byte) string {
492→	lines, err := transcript.ParseFromBytes(data)
493→	if err != nil {
494→		return ""
495→	}
496→
497→	for _, line := range lines {
498→		if line.Type != transcript.TypeAssistant {
499→			continue
500→		}
501→		var msg struct {
502→			Model string `json:"model"`
503→		}
504→		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
505→			return msg.Model
506→		}
507→	}
508→	return ""
509→}
