511→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
512→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
513→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
514→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
515→func estimateSessionDuration(data []byte) int64 {
516→	type timestamped struct {
517→		Timestamp string `json:"timestamp"`
518→	}
519→
520→	var first, last time.Time
521→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
522→		if len(rawLine) == 0 {
523→			continue
524→		}
525→		var ts timestamped
526→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
527→			continue
528→		}
529→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
530→		if err != nil {
531→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
532→			if err != nil {
533→				continue
534→			}
535→		}
536→		if first.IsZero() {
537→			first = parsed
538→		}
539→		last = parsed
540→	}
541→
542→	if first.IsZero() || last.IsZero() || !last.After(first) {
543→		return 0
544→	}
545→	return last.Sub(first).Milliseconds()
546→}
