 1→import type { TranscriptMessage, ToolCall } from "../../types";
 2→import type { TranscriptParser, TranscriptParseResult } from "./types";
 3→
 4→interface GeminiRawMessage {
 5→  id?: string;
 6→  type?: string;
 7→  content?: string;
 8→  timestamp?: string;
 9→  toolCalls?: Array<{
10→    id: string;
11→    name: string;
12→    args?: Record<string, unknown>;
13→  }>;
14→}
15→
16→interface GeminiLog {
17→  messages?: GeminiRawMessage[];
18→}
19→
20→function extractToolCalls(
21→  msg: GeminiRawMessage,
22→  timestamp: string,
23→): ToolCall[] | undefined {
24→  if (!msg.toolCalls || msg.toolCalls.length === 0) return undefined;
25→
26→  return msg.toolCalls.map((tc) => ({
27→    id: tc.id,
28→    name: tc.name,
29→    input: (tc.args ?? {}) as Record<string, unknown>,
30→    timestamp,
31→  }));
32→}
33→
34→/**
35→ * Parse a Gemini CLI transcript into TranscriptMessage[].
36→ * Format: single JSON object with a `messages` array.
37→ * User messages have type "user", assistant messages have type "gemini".
38→ */
39→function parseGeminiTranscript(jsonContent: string): TranscriptMessage[] {
40→  let log: GeminiLog;
41→  try {
42→    log = JSON.parse(jsonContent);
43→  } catch {
44→    return [];
45→  }
46→
47→  if (!Array.isArray(log.messages)) return [];
48→
49→  const messages: TranscriptMessage[] = [];
50→
51→  for (const msg of log.messages) {
52→    if (msg.type !== "user" && msg.type !== "gemini") continue;
53→
54→    const role: "user" | "assistant" =
55→      msg.type === "user" ? "user" : "assistant";
56→    const timestamp = msg.timestamp || new Date().toISOString();
57→
58→    messages.push({
59→      id: msg.id || crypto.randomUUID(),
60→      role,
61→      content: msg.content ?? "",
62→      timestamp,
63→      toolCalls:
64→        role === "assistant" ? extractToolCalls(msg, timestamp) : undefined,
65→    });
66→  }
67→
68→  return messages;
69→}
70→
71→/**
72→ * Parser for Gemini CLI transcripts.
73→ */
74→export class GeminiParser implements TranscriptParser {
75→  readonly name = "Gemini CLI";
76→
77→  parse(jsonContent: string): TranscriptParseResult {
78→    const messages = parseGeminiTranscript(jsonContent);
79→
80→    return {
81→      messages,
82→      isFallback: false,
83→    };
84→  }
85→}
