158→// writeTranscript writes transcript lines to a file in JSONL format.
159→func writeTranscript(path string, transcript []transcriptLine) error {
160→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
161→	if err != nil {
162→		return fmt.Errorf("failed to create file: %w", err)
163→	}
164→	defer func() { _ = file.Close() }()
165→
166→	for _, line := range transcript {
167→		data, err := json.Marshal(line)
168→		if err != nil {
169→			return fmt.Errorf("failed to marshal line: %w", err)
170→		}
171→		if _, err := file.Write(data); err != nil {
172→			return fmt.Errorf("failed to write line: %w", err)
173→		}
174→		if _, err := file.WriteString("\n"); err != nil {
175→			return fmt.Errorf("failed to write newline: %w", err)
176→		}
177→	}
178→
179→	return nil
180→}
