328→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
329→// When force is true, it amends without prompting.
330→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
331→	// Get HEAD commit info
332→	repo, err := openRepository(ctx)
333→	if err != nil {
334→		return fmt.Errorf("failed to open repository: %w", err)
335→	}
336→	headRef, err := repo.Head()
337→	if err != nil {
338→		return fmt.Errorf("failed to get HEAD: %w", err)
339→	}
340→	headCommit, err := repo.CommitObject(headRef.Hash())
341→	if err != nil {
342→		return fmt.Errorf("failed to get HEAD commit: %w", err)
343→	}
344→
345→	shortHash := headRef.Hash().String()[:7]
346→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
347→
348→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
349→
350→	amend := true
351→	if !force {
352→		form := NewAccessibleForm(
353→			huh.NewGroup(
354→				huh.NewConfirm().
355→					Title("Amend the last commit in this branch?").
356→					Affirmative("Y").
357→					Negative("n").
358→					Value(&amend),
359→			),
360→		)
361→		if err := form.Run(); err != nil {
362→			return fmt.Errorf("prompt failed: %w", err)
363→		}
364→	}
365→
366→	if !amend {
367→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
368→		return nil
369→	}
370→
371→	// Amend the commit with the checkpoint trailer.
372→	// If the message already has trailers, append on a new line; otherwise add a blank line first.
373→	trimmed := strings.TrimRight(headCommit.Message, "\n")
374→	trailer := fmt.Sprintf("%s: %s", trailers.CheckpointTrailerKey, checkpointIDStr)
375→	var newMessage string
376→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
377→		// Already has at least one Entire-Checkpoint trailer — append directly
378→		newMessage = fmt.Sprintf("%s\n%s\n", trimmed, trailer)
379→	} else {
380→		newMessage = fmt.Sprintf("%s\n\n%s\n", trimmed, trailer)
381→	}
382→
383→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
384→	if output, err := cmd.CombinedOutput(); err != nil {
385→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
386→	}
387→
388→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
389→	return nil
390→}
