392→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
393→// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
394→func extractFirstPromptFromTranscript(data []byte) string {
395→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
396→	lines, err := transcript.ParseFromBytes(data)
397→	if err == nil {
398→		for _, line := range lines {
399→			if line.Type == transcript.TypeUser {
400→				prompt := extractTextFromMessage(line.Message)
401→				if prompt != "" {
402→					return prompt
403→				}
404→			}
405→		}
406→	}
407→
408→	// Fallback: try Gemini JSON format {"messages": [...]}
409→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
410→		return prompts[0]
411→	}
412→
413→	return ""
414→}
415→
416→// extractTextFromMessage extracts the text content from a transcript message.
417→func extractTextFromMessage(msg json.RawMessage) string {
418→	// Try string content first (simple user messages)
419→	var simple struct {
420→		Content string `json:"content"`
421→	}
422→	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
423→		return simple.Content
424→	}
425→
426→	// Try array content (messages with tool results, text blocks, etc.)
427→	var array struct {
428→		Content []struct {
429→			Type string `json:"type"`
430→			Text string `json:"text"`
431→		} `json:"content"`
432→	}
433→	if err := json.Unmarshal(msg, &array); err == nil {
434→		for _, block := range array.Content {
435→			if block.Type == "text" && block.Text != "" {
436→				return block.Text
437→			}
438→		}
439→	}
440→
441→	return ""
442→}
443→
444→// normalizeGeminiTranscript re-serializes a Gemini JSON transcript so that all
445→// content fields are plain strings. Gemini user messages store content as
446→// [{"text":"..."}] arrays, but the UI expects string content. Parsing through
447→// geminicli.ParseTranscript normalizes this via GeminiMessage.UnmarshalJSON.
448→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
449→	parsed, err := geminicli.ParseTranscript(data)
450→	if err != nil {
451→		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
452→	}
453→	normalized, err := json.MarshalIndent(parsed, "", "  ")
454→	if err != nil {
455→		return nil, fmt.Errorf("failed to re-serialize Gemini transcript: %w", err)
456→	}
457→	return normalized, nil
458→}
459→
460→// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
461→// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
462→func countUserTurns(data []byte) int {
463→	// Try JSONL format first — use extractTextFromMessage to distinguish
464→	// real user prompts from tool_result messages (both have type "user").
465→	lines, err := transcript.ParseFromBytes(data)
466→	if err == nil {
467→		count := 0
468→		for _, line := range lines {
469→			if line.Type == transcript.TypeUser {
470→				if extractTextFromMessage(line.Message) != "" {
471→					count++
472→				}
473→			}
474→		}
475→		if count > 0 {
476→			return count
477→		}
478→	}
479→
480→	// Fallback: Gemini JSON format
481→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
482→		return len(prompts)
483→	}
484→
485→	return 0
486→}
487→
488→// extractModelFromTranscript extracts the model name from a JSONL transcript.
489→// Best-effort: returns empty string if the transcript format doesn't include model info
490→// (e.g., Gemini stores model info in hook events, not the transcript).
491→func extractModelFromTranscript(data []byte) string {
492→	lines, err := transcript.ParseFromBytes(data)
493→	if err != nil {
494→		return ""
495→	}
496→
497→	for _, line := range lines {
498→		if line.Type != transcript.TypeAssistant {
499→			continue
500→		}
501→		var msg struct {
502→			Model string `json:"model"`
503→		}
504→		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
505→			return msg.Model
506→		}
507→	}
508→	return ""
509→}
510→
511→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
512→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
513→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
514→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
515→func estimateSessionDuration(data []byte) int64 {
516→	type timestamped struct {
517→		Timestamp string `json:"timestamp"`
518→	}
519→
520→	var first, last time.Time
521→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
522→		if len(rawLine) == 0 {
523→			continue
524→		}
525→		var ts timestamped
526→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
527→			continue
528→		}
529→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
530→		if err != nil {
531→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
532→			if err != nil {
533→				continue
534→			}
535→		}
536→		if first.IsZero() {
537→			first = parsed
538→		}
539→		last = parsed
540→	}
541→
542→	if first.IsZero() || last.IsZero() || !last.After(first) {
543→		return 0
544→	}
545→	return last.Sub(first).Milliseconds()
546→}
