func resolveAndValidateTranscript(ctx context.Context, sessionID string, agentName types.AgentName, ag agent.Agent) (string, error) {
	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
	if err != nil {
		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
	}
	// Agents use cwd-derived project directories, so the transcript may be stored under
	// a different project directory if the session was started from a different working directory.
	if _, statErr := os.Stat(transcriptPath); statErr == nil {
		return transcriptPath, nil
	}
	if found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag); searchErr == nil {
		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
		return found, nil
	} else {
		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
	}
	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
}

// setupAttachTestRepo creates a temp git repo with one commit and enables Entire.
// Returns the repo directory. Caller must not use t.Parallel() (uses t.Chdir).
func setupAttachTestRepo(t *testing.T) string {
	t.Helper()
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "init.txt", "init")
	testutil.GitAdd(t, tmpDir, "init.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)
	enableEntire(t, tmpDir)
	return tmpDir
}

// setupClaudeTranscript creates a fake Claude transcript file and returns the session directory.
func setupClaudeTranscript(t *testing.T, sessionID, content string) {
	t.Helper()
	claudeDir := t.TempDir()
	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", claudeDir)
	if err := os.WriteFile(filepath.Join(claudeDir, sessionID+".jsonl"), []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
}

